import contextlib
import io
import json
import os
import shutil
import signal
import sys
import tempfile
import traceback

BASE = os.getcwd()
CANDIDATE_FILE = os.path.join(BASE, 'block-2.txt')
INPUTS_FILE = os.path.join(BASE, 'inputs.json')


class CaseTimeout(Exception):
    pass


def _on_alarm(signum, frame):
    raise CaseTimeout('candidate exceeded 5 second limit')


def run_candidate(source, payload):
    tmpdir = tempfile.mkdtemp(prefix='case_')
    old_cwd = os.getcwd()
    old_path = list(sys.path)
    try:
        with open(os.path.join(tmpdir, 'data.json'), 'w', encoding='utf-8') as f:
            json.dump(payload, f)
        os.chdir(tmpdir)
        ns = {'__name__': 'candidate_main', '__file__': os.path.join(tmpdir, 'main.py')}
        code = compile(source, 'main.py', 'exec')
        out_buf = io.StringIO()
        err_buf = io.StringIO()
        old_handler = signal.signal(signal.SIGALRM, _on_alarm)
        signal.alarm(5)
        try:
            with contextlib.redirect_stdout(out_buf), contextlib.redirect_stderr(err_buf):
                exec(code, ns)
        except CaseTimeout as exc:
            return {'error': str(exc)}
        except BaseException as exc:
            return {'error': type(exc).__name__ + ': ' + str(exc)}
        finally:
            signal.alarm(0)
            signal.signal(signal.SIGALRM, old_handler)
        if 'result_dict' not in ns:
            return {'error': 'candidate did not define result_dict'}
        try:
            value = json.loads(json.dumps(ns['result_dict']))
        except (TypeError, ValueError) as exc:
            return {'error': 'result not JSON serializable: ' + str(exc)}
        return {'actual': value}
    finally:
        os.chdir(old_cwd)
        sys.path[:] = old_path
        shutil.rmtree(tmpdir, ignore_errors=True)


def main():
    results = []
    try:
        with open(CANDIDATE_FILE, 'r', encoding='utf-8') as f:
            source = f.read()
        with open(INPUTS_FILE, 'r', encoding='utf-8') as f:
            cases = json.load(f)
    except Exception:
        print(json.dumps({'results': [], 'harness_error': traceback.format_exc()}))
        return
    harness_error = None
    for case in cases:
        cid = case.get('id') if isinstance(case, dict) else None
        payload = case.get('input') if isinstance(case, dict) else None
        try:
            outcome = run_candidate(source, payload)
        except Exception:
            harness_error = traceback.format_exc()
            break
        entry = {'id': cid}
        entry.update(outcome)
        results.append(entry)
    final = {'results': results}
    if harness_error is not None:
        final['harness_error'] = harness_error
    print(json.dumps(final))


if __name__ == '__main__':
    main()
